<template>
  <section class="cost-page">
    <header class="cost-page-heading"><div><h2>داشبورد کنترل هزینه</h2><p>نمای کلی هزینه‌ها و وضعیت بهای تولید در بازه انتخاب‌شده.</p></div></header>
    <form class="cost-filter" @submit.prevent="load"><JalaliDatePicker v-model="filters.start_date" placeholder="از تاریخ"/><JalaliDatePicker v-model="filters.end_date" placeholder="تا تاریخ"/><button class="cost-primary" :disabled="loading">{{loading?'در حال دریافت…':'اعمال بازه'}}</button><button type="button" class="cost-text" @click="clearRange">همه تاریخ‌ها</button></form>
    <div v-if="error" class="cost-notice" role="alert">{{error}} <button @click="load">تلاش مجدد</button></div>
    <div v-if="loading" class="dashboard-loading">در حال دریافت گزارش…</div>
    <template v-else>
      <div class="overview-metrics"><article><span>کل هزینه‌های ثبت‌شده</span><strong>{{money(dashboard.total_expenses)}}</strong><small>{{number(dashboard.expense_count)}} مورد</small></article><article><span>هزینه تولیدهای تکمیل‌شده</span><strong>{{money(dashboard.completed_order_cost)}}</strong><small>{{number(dashboard.completed_item_count)}} واحد تکمیل‌شده</small></article><article><span>هزینه سربار دوره</span><strong>{{money(dashboard.overhead_total)}}</strong><small>ثبت‌شده در مدیریت هزینه</small></article><article><span>سود تولیدهای تکمیل‌شده</span><strong :class="Number(dashboard.completed_order_profit)<0?'loss':'profit'">{{money(dashboard.completed_order_profit)}}</strong><small>بر اساس تولیدهای انجام‌شده</small></article></div>
      <div class="dashboard-grid">
        <section><header><h3>هزینه بر اساس دسته‌بندی</h3><RouterLink to="/dashboard/cost-control/expenses">مشاهده هزینه‌ها</RouterLink></header><div v-for="row in dashboard.expense_by_category" :key="row.category_id" class="dashboard-row"><span>{{row.category__name}}</span><strong>{{money(row.total)}}</strong><small>{{number(row.count)}} هزینه</small></div><p v-if="!dashboard.expense_by_category?.length" class="empty-resource">در این بازه هزینه‌ای ثبت نشده است.</p></section>
        <section><header><h3>محصولات با بیشترین هزینه</h3><RouterLink to="/dashboard/cost-control/production-costs">جزئیات تولید</RouterLink></header><div v-for="product in dashboard.highest_cost_products" :key="product.id" class="dashboard-row"><span>{{product.name}}</span><strong>{{money(product.final_production_cost)}}</strong><small>{{number(product.profit_margin)}}٪ حاشیه سود</small></div><p v-if="!dashboard.highest_cost_products?.length" class="empty-resource">محصولی برای تحلیل وجود ندارد.</p></section>
        <section><header><h3>روند هزینه‌های ثبت‌شده</h3><RouterLink to="/dashboard/cost-control/reports">گزارش‌ها</RouterLink></header><div v-for="row in dashboard.expense_trend" :key="row.period" class="dashboard-row"><span>{{month(row.period)}}</span><strong>{{money(row.total)}}</strong><small>{{number(row.count)}} مورد</small></div><p v-if="!dashboard.expense_trend?.length" class="empty-resource">روندی برای نمایش وجود ندارد.</p></section>
        <section><header><h3>آخرین فعالیت هزینه</h3></header><div v-for="row in dashboard.recent_cost_activity" :key="row.id" class="dashboard-row"><span>{{row.title}}</span><strong>{{money(row.amount)}}</strong><small>{{row.category}} · {{date(row.date)}}</small></div><p v-if="!dashboard.recent_cost_activity?.length" class="empty-resource">فعالیت جدیدی وجود ندارد.</p></section>
        <section class="wide-section"><header><h3>بیشترین اختلاف هزینه تولید</h3><RouterLink to="/dashboard/cost-control/production-costs">تحلیل اختلاف‌ها</RouterLink></header><div v-for="row in costChanges" :key="row.id" class="dashboard-row"><span>{{row.name}}</span><strong :class="Number(row.variance)>0?'loss':'profit'">{{signedMoney(row.variance)}}</strong><small>هزینه مورد انتظار {{money(row.expected_cost)}} · هزینه واقعی {{money(row.actual_unit_cost)}}</small></div><p v-if="!costChanges.length" class="empty-resource">هنوز تولید تکمیل‌شده‌ای برای محاسبه اختلاف وجود ندارد.</p></section>
      </div>
    </template>
  </section>
</template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import API from'@/api/product-cost.api.js';import JalaliDatePicker from'@/components/cost/JalaliDatePicker.vue';import{costErrorMessage,formatCostNumber as number,formatMoney as money}from'@/utils/costControl';const loading=ref(false),error=ref(''),filters=reactive({start_date:'',end_date:''}),dashboard=reactive({total_expenses:0,expense_count:0,overhead_total:0,completed_order_cost:0,completed_order_profit:0,completed_item_count:0,expense_by_category:[],highest_cost_products:[],expense_trend:[],recent_cost_activity:[],production_costs:[]}),costChanges=computed(()=>(dashboard.production_costs||[]).filter(row=>row.variance!==null).slice().sort((a,b)=>Math.abs(Number(b.variance))-Math.abs(Number(a.variance))).slice(0,5));async function load(){if(loading.value)return;loading.value=true;error.value='';try{Object.assign(dashboard,await API.dashboard({...filters}))}catch(cause){error.value=costErrorMessage(cause)}finally{loading.value=false}}function clearRange(){filters.start_date='';filters.end_date='';load()}const date=value=>value?new Intl.DateTimeFormat('fa-IR-u-ca-persian',{dateStyle:'medium',timeZone:'Asia/Tehran'}).format(new Date(value)):'—',month=value=>value?new Intl.DateTimeFormat('fa-IR-u-ca-persian',{year:'numeric',month:'long',timeZone:'Asia/Tehran'}).format(new Date(value)):'—',signedMoney=value=>`${Number(value)>0?'+':''}${money(value)}`;onMounted(load)</script>
<style scoped>.overview-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.overview-metrics article{display:grid;gap:5px;padding:14px;background:var(--surface);border:1px solid var(--border);border-radius:11px}.overview-metrics span,.overview-metrics small{color:var(--muted);font-size:.7rem}.overview-metrics strong{font-size:1rem}.dashboard-grid section>header{display:flex;justify-content:space-between;gap:10px}.dashboard-grid section>header a{color:var(--primary);font-size:.7rem;text-decoration:none}@media(max-width:850px){.overview-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:430px){.overview-metrics{grid-template-columns:1fr}}</style>
